package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    attribute currentPositionDeg : Integer := 0;
    attribute directionForward : Boolean := true;
    attribute moving : Boolean := true;
    attribute reportPending : Boolean := true;
    perform action tick {
      first start;
      then if moving {
        first start;
        then if directionForward {
          first start;
          then if currentPositionDeg < 180 {
            first start;
            then assign currentPositionDeg := currentPositionDeg + 1;
          } else {
            first start;
            then assign moving := false;
            then assign reportPending := true;
          }
        } else {
          first start;
          then if currentPositionDeg > 0 {
            first start;
            then assign currentPositionDeg := currentPositionDeg - 1;
          } else {
            first start;
            then assign moving := false;
            then assign reportPending := true;
          }
        }
      } else {
        first start;
        then if reportPending {
          first start;
          then assign reportPending := false;
          then assign directionForward := not directionForward;
          then assign moving := true;
        }
      }
    }
    out attribute io_0 : Real = currentPositionDeg;
    out attribute serial_0_trigger : Boolean = reportPending;
    out attribute serial_0_value_0 : Integer = (if reportPending ? currentPositionDeg else 0);
  }
  part system : Controller;
}
